-- 022: R32 stubs become full guides (PCV/valve cover, crack pipe, timing chains, intake, exhaust)
update tasks set live = true, title = 'Coolant pipe (''crack pipe'') & thermostat housing (VR6)', time_label = '5–6 hr', difficulty = 3 where id = 'coolant-pipe-r32';
update guides set content = $j${"id": "coolant-pipe-r32", "title": "Coolant pipe ('crack pipe') & thermostat housing (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "crackpipe-hero", "alsoFits": "24V VR6: Mk4 R32, 24V GTI/Jetta, A3/TT 3.2 (pipe 022 121 050); 12V VR6 uses a different pipe", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "5–6 hr (with the manifold off)", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$60–200 pipe · $60–150 housing · $30 coolant", "risk": "Coolant everywhere · plastic and aluminium threads · air in the system afterward", "why": "Two plastic parts carry coolant across the top of the VR6: the distribution pipe from the back of the water pump to the thermostat housing, and the housing itself. Both go brittle with heat cycles and both leak, which is why the pipe earned its nickname. You replace them together, with the thermostat and the sensor seals, and billet aluminium versions of the pipe exist so you never do it again.", "note": "R32 owners do this as a preventive job; several did it alongside the SAI delete for room. The access is the intake-manifold-off procedure from the PCV guide."}, "heroCap": "Under the intake manifold: the pipe runs along the head from the water pump at the back to the thermostat housing at the front, with the temperature sensor in the housing. Plastic, plastic, plastic.", "lifespan": {"title": "When to expect it", "headline": ["Commonly weeping by 80,000–120,000 miles or 12–15 years, whichever comes first"], "earliest": "Cracks reported at 60k on hot-climate cars", "detail": "Coolant smell after a drive, a slowly dropping level with no puddle, pink crust on top of the block under the manifold. The thermostat housing's seals and the pipe's o-rings go around the same time the plastic does. Owners who replaced the pipe with aluminium years ago report the plastic housing was the next to go.", "factors": ["Age of the plastic", "Heat cycles", "An SAI system in the way (deleting it frees the area)"], "inspect": ["Coolant level at every fill-up for a month if you smell it", "Flashlight along the top of the block below the manifold: pink crust"], "confidence": {"level": "high", "n": 4, "note": "Vendor listings (ECS, Gruven, iABED) and R32 forums agree on the failure and the fix."}}, "should": {"yesIf": ["Coolant smell or loss with no visible puddle", "Pink crust under the intake manifold", "Thermostat codes or slow warm-up (P0128)", "Doing the PCV / valve cover anyway"], "codes": ["P0128", "P2181"], "notes": ["Pipe: OE 022 121 050 (plastic) or a billet aluminium replacement (GruvenParts, iABED, ECS) with a drain plug. The aluminium pipe is the one to buy; it turns a repeat job into a one-time job.", "Housing: replace the complete thermostat housing with new seals and a new thermostat. Aluminium housings exist too but were out of stock for years; plastic with fresh seals is fine if that's what you can get.", "New o-rings everywhere the pipe seats, and new sensor o-rings. The pipe seats into the housing and the pump with o-rings; owners who reused them leaked again.", "This guide assumes the intake manifold comes off (the PCV guide's access). Some Mk4 owners reach the pipe from below with the manifold on; on the Mk5 the manifold-off route is the one that doesn't cost you a knuckle."], "confidence": {"level": "medium", "n": 4, "note": "Parts and failure pattern well documented; step detail synthesized from 24V listings, the FCP manifold procedure and owner threads. Torques flagged."}}, "parts": [{"tier": "aftermarket", "name": "Billet aluminium coolant pipe (with drain plug)", "pn": "GruvenParts / iABED / ECS 24V", "note": "Replaces 022 121 050", "price": "$150–220", "links": []}, {"tier": "oe", "name": "Coolant pipe, plastic (if you insist)", "pn": "022 121 050", "note": "", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Thermostat housing with seals", "pn": "022 121 111 (confirm by VIN)", "note": "", "price": "$60–150", "links": []}, {"tier": "oe", "name": "Thermostat (87°C) and o-ring", "pn": "—", "note": "Often in the housing kit", "price": "$30", "links": []}, {"tier": "oe", "name": "Coolant temp sensor (G62) and o-rings", "pn": "06A 919 501 A (confirm)", "note": "Cheap, replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Intake manifold gasket, pipe o-rings", "pn": "kit", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "G13 coolant concentrate + distilled water", "pn": "G 013 A8J 1G", "note": "About a gallon of concentrate", "price": "$30", "links": []}], "aftermarket": [{"name": "GruvenParts billet crack pipe (24V)", "note": "Lifetime warranty, optional drain valve; they've made these longer than anyone.", "price": "$180–220", "signal": "The original fix", "links": [{"store": "GruvenParts", "url": "https://www.gruvenparts.com/"}]}, {"name": "iABED billet coolant pipe", "note": "Billet with a steel drain plug; 24V VR6 fitment incl. Mk5 R32.", "price": "$150–200", "signal": "Value billet", "links": []}, {"name": "ECS aluminium pipe", "note": "'Engineered to be the last water pipe you'll need to replace.' Same idea.", "price": "$150–200", "signal": "Also fine", "links": []}, {"name": "Eurowise / aluminium thermostat housing", "note": "Metal housing for the other half of the problem, when in stock.", "price": "$150–250", "signal": "If you can get one", "links": []}], "tools": [{"name": "Everything from the PCV guide's manifold procedure (10mm/16mm, 5/6mm hex, 10mm TS, T20–T30)"}, {"name": "Hose-clamp pliers, picks, big drain pans, towels"}, {"name": "Vacuum coolant fill tool (strongly recommended) or a funnel"}], "before": ["Engine cold. Coolant under pressure scalds.", "Drain first, then start on the top of the engine; there's a litre sitting in the pipe.", "Read the PCV guide's access steps; they're reused here word for word."], "steps": [{"n": 1, "title": "Drain the coolant", "blocks": [{"t": "text", "b": "Belly pan off. Lower radiator hose off at the radiator into a pan; reservoir cap off to speed it. Leave the pan; the pipe holds more."}]}, {"n": 2, "title": "Nose to service position", "blocks": [{"t": "text", "b": "Bumper cover off: eight T25s along the bottom edge, three T25s in each wheel well, both lower grilles (T20), unplug the side markers through the grille openings, disconnect the washer-bottle suction hose (have a pan), four T25s under the lower grilles and two T20s in the main grille opening, two T25s at the top corners by the headlights, then the two T25s to the bumper beam. Pull each corner forward and set the cover somewhere safe."}, {"t": "text", "b": "Behind each headlight, remove the two rear-most T30s. Unclip the hood cable behind the driver's headlight. Remove the top four 16mm bumper-beam bolts and loosen the bottom four almost all the way. Pull the top of the radiator support forward: the nose tilts and the engine opens up."}, {"t": "note", "b": "Twenty minutes that turns a knuckle-buster into a job you can see. Every R32 engine-top write-up does it."}]}, {"n": 3, "title": "Intake manifold off", "blocks": [{"t": "text", "b": "Airbox out (clips and tabs; lift). Harness bracket on the driver's side of the head: 10mm nut and stud at the back, T30 at the front; unplug the three throttle-body-side connectors and lay the harness aside. Coil connectors off (lift the tabs with a pick), harness cover off. Walk the main PCV breather hose off the top of the valve cover with a flat screwdriver. Behind the manifold: four vacuum lines by hand and the bracket (10mm triple-square). Throttle body: four 5mm hex. Fuel-line bracket (10mm) on the passenger side. One 10mm triple-square bolt each side of the manifold. Two T30 brackets at the front (dipstick tube, sensors). Vacuum line off the variable-intake solenoid."}, {"t": "text", "b": "Nine manifold bolts, all at the front, long ball-end 6mm hex. Pry the six coils out of the head with a flat screwdriver. Rock the manifold forward to break the gasket's seal and lift it away."}, {"t": "ill", "id": "vr6-top-hero", "cap": "What's under the manifold: valve cover with the oil separator at its front, and the coolant pipe running along the head to the thermostat housing."}, {"t": "warn", "b": "Six open intake ports. Rag them immediately. A dropped bolt into a VR6 port is a head-off job."}]}, {"n": 4, "title": "Sensor, hoses, housing off", "blocks": [{"t": "text", "b": "Unplug the coolant temperature sensor on the thermostat housing and pull its retaining clip. Release the hoses at the housing (clamps). Housing bolts out (10mm; count them), housing off the head with the thermostat. Note the thermostat's orientation."}, {"t": "ill", "id": "crackpipe-hero", "cap": "Pipe from the pump at the back of the head to the housing at the front. Both ends are o-ring joints."}, {"t": "warn", "b": "Aluminium threads under old plastic. Back the bolts out slowly; if one squeaks, stop and oil it. Cross-threading here is a helicoil job with the engine in the car."}]}, {"n": 5, "title": "Pipe out", "caution": true, "blocks": [{"t": "text", "b": "Release any bracket bolt on the pipe. Pull the pipe forward out of the water pump's port (o-ring joint at the back); it comes out toward the front now that the housing is off. Expect the last of the coolant. Look at the old pipe: a hairline at a hose spigot or the pump end is the usual crack."}, {"t": "warn", "b": "If the pipe won't move, it's the o-ring, not a bolt you missed. Twist and pull; don't pry against the head."}]}, {"n": 6, "title": "New pipe and housing", "blocks": [{"t": "text", "b": "Clean both o-ring bores (pump port and housing seat) and the housing face on the head. New o-rings on the pipe, wetted with coolant; pipe into the pump port first, fully seated. New thermostat in the new housing in the orientation you noted, new seal, housing onto the head and onto the pipe's front end together; bolts snug in a criss-cross. New sensor with its o-ring and clip. Hoses and clamps."}, {"t": "torque", "label": "Thermostat housing bolts (M6)", "nm": 10, "c": {"level": "single", "n": 1, "note": "No factory figure confirmed this pass; M6 into aluminium, 10 Nm is the usual VW value and owners say 'snug'. Flagged."}}]}, {"n": 7, "title": "Manifold on, engine dressed, nose back", "blocks": [{"t": "text", "b": "New manifold gasket pressed into the manifold (pick the old one out; wipe the head face). Manifold on with nothing trapped; all nine bolts started by hand, then tightened middle-out."}, {"t": "torque", "label": "Intake manifold bolts (6mm hex ×9)", "nm": 13, "c": {"level": "high", "n": 1, "note": "13 Nm (FCP Euro procedure on a Mk5 R32)."}}, {"t": "text", "b": "Brackets (T30), variable-intake vacuum line, coils in (tab side per the connectors), harness and cover, manifold side bolts (10mm TS), driver's-side harness bracket (ground stud at the rear hole), PCV breather hose onto the cover, fuel-line bracket, four vacuum lines and their bracket, throttle body (5mm hex, hand-start), airbox and MAF."}, {"t": "text", "b": "Nose: lift it back, four T30s behind the headlights, top beam bolts by hand then all eight to torque (16mm), then the cover in reverse: two beam T25s, side markers, washer hose, grilles, corner screws, bottom edge, wheel wells."}]}, {"n": 8, "title": "Fill and bleed", "caution": true, "blocks": [{"t": "text", "b": "Lower hose on. Fill with 50/50 G13, ideally with a vacuum fill tool, which pulls the air out of the pipe and the heater core in one go. Without one: fill slowly, cap off, heater on hot, idle until the thermostat opens and the level drops, top up, repeat, cap on."}, {"t": "warn", "b": "Air pocket at the thermostat means the gauge reads cold and then spikes. Watch it the whole first warm-up."}]}, {"n": 9, "title": "Heat-cycle and re-check", "blocks": [{"t": "text", "b": "Drive, cool fully, top up. Flashlight along the head under the manifold after three heat cycles. Belly pan on when it's dry."}]}], "alsoReplace": [{"name": "Oil separator (PCV) and valve cover gasket", "why": "Same access. Do them now (its guide)."}, {"name": "Coolant hoses at the housing", "why": "Hardened at both ends; cheap now, a leak later."}, {"name": "Water pump", "why": "The pipe seats into it; if the pump is original at 100k, forums say do it."}, {"name": "SAI delete", "why": "Owners who removed the secondary air pump and hoses got the room back permanently. Emissions-legal status varies; decide for yourself."}], "check": {"tab": "Where's the leak?", "title": "Where is the coolant going?", "illId": "crackpipe-hero", "illCap": "Crust tells you which end.", "rows": [{"see": "Crust at the front, by the housing", "means": "Housing seals or the pipe's front o-ring.", "do": "Both parts anyway."}, {"see": "Crust toward the back of the head", "means": "Pipe at the pump end.", "do": "Pipe + o-rings; housing while you're there."}, {"see": "No trace, level dropping", "means": "Heater core or internal.", "do": "Pressure test before opening the top of the engine."}], "c": {"level": "community", "n": 3, "note": "Owner threads."}}, "aftercare": ["Level check after each of the first three drives.", "Aluminium pipe with a drain plug: future flushes are five minutes."], "disagreements": [{"topic": "Manifold off?", "pos": "Mk4 owners sometimes reach under.", "call": "Off. It's the FCP procedure and you'll want the room."}, {"topic": "Plastic or billet pipe?", "pos": "Plastic is cheaper.", "call": "Billet. This is the job you don't want to do twice."}], "sources": ["GruvenParts, iABED and ECS 24V crack pipe listings (part supersession, drain plug)", "R32OC 'MK5 R32 crack pipe and thermostat housing' thread", "VWVortex 'Common MKV R32 Issues Report'", "Humble Mechanic R32 thermostat/crack pipe video (24V, Mk4)", "FCP Euro Mk5 R32 valve cover procedure (manifold access, torques)", "VWVortex 12V crack pipe DIY (technique)"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'coolant-pipe-r32';
update tasks set live = true, title = 'Timing chains, guides & tensioners (VR6)', time_label = '2–3 days', difficulty = 5 where id = 'timing-chain-r32';
update guides set content = $j${"id": "timing-chain-r32", "title": "Timing chains, guides & tensioners (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "vr6-chain-hero", "alsoFits": "24V VR6 (Mk4 R32, A3/TT 3.2) for the chain layout; 12V VR6 uses different parts", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "2–3 days · 20–30 hr", "timeRepeat": "—", "difficulty": 5, "cost": "$400–700 parts · $150 tools · plus everything you touch on the way", "risk": "Engine timing · transmission and 4Motion driveline out · the biggest job in this catalog", "why": "The VR6's two timing chains live at the back of the engine against the firewall. Their plastic guide rails wear and the upper tensioner loses grip; the warning is a rattle at idle from the transmission side. Left alone, a guide breaks and the chain jumps. On a Mk5 R32 the chains are behind the DSG, and the DSG has a bevel box and a propshaft bolted to it, so the honest version of this guide is: the chain work is a day, and getting to it is the other two.", "note": "The chain procedure follows the VR6 DIY community has used for twenty years; the 24V parts and cam locks differ from the 12V and are flagged. Access on a 4Motion DSG car is described at the level owners report, not step by step."}, "heroCap": "Back of the engine: the upper chain from the cams down to the intermediate shaft, the lower chain from the intermediate shaft to the crank, each with a guide rail and a tensioner rail. The upper covers come off with the transmission out of the way.", "lifespan": {"title": "When to expect it", "headline": ["Listen from 100,000 miles; act on a rattle"], "earliest": "Guide failures reported from 80k", "detail": "A rattle or ticking at idle from the rear of the engine that changes with revs is the guides or the tensioner. Many VR6s go 200k on the original chains; the plastic rails don't. Once a rail breaks up, pieces end up in the pan and the chain runs loose. That's the point of no return.", "factors": ["Mileage", "Oil change neglect (the tensioner is oil-fed)", "Hard cold starts"], "inspect": ["Cold and warm idle with the hood up and an ear at the transmission side. New noise from the rear is this.", "Oil pan magnet at every change: plastic flakes are guide material."], "confidence": {"level": "high", "n": 4, "note": "Universal in VR6 forums, R32 buyer's guides and the 12V DIY thread."}}, "should": {"yesIf": ["Rattle from the rear of the engine at idle", "Plastic in the oil", "Past 150k with unknown history and you're keeping the car", "Transmission is coming out for another reason (clutch isn't a thing on a DSG car, but a rear main seal or a DSG is)"], "codes": ["P0016", "P0341"], "notes": ["Scope honestly. Chain work: 2–8 hours once you can see the covers (the 12V DIY's own estimate). Getting there on a Mk5 R32: subframe, exhaust, propshaft and bevel box, DSG out, or the engine out. Most owners who've done it either pull the engine or pay a specialist for the access and do the chains themselves.", "Parts are 24V-specific. Buy a complete 24V VR6 timing kit (chains, both guide rails, both tensioner rails, upper tensioner, gaskets) rather than piecing it; the 12V part numbers in the famous Vortex DIY do not fit this engine.", "Cam locks: the 24V needs its own cam-locking tool; the 12V's 3268 plate (or the aluminium-plate trick) doesn't fit 24V cams. Rent or buy the 24V VR6 timing tool set.", "Rear main seal: it's right there once the flywheel/DSG side is open. Do it."], "confidence": {"level": "medium", "n": 4, "note": "Chain layout and technique from the VR6 DIY corpus; 24V specifics and 4Motion access at owner-report level. Torques flagged where they come from the 12V DIY."}}, "parts": [{"tier": "oe", "name": "24V VR6 timing chain kit: upper + lower chains, guide rails, tensioner rails, upper tensioner, gaskets", "pn": "e.g. INA/Febi 24V kit (confirm for BUB)", "note": "Not the 12V kit", "price": "$350–600", "links": []}, {"tier": "oe", "name": "Rear main seal", "pn": "068 198 171 / 24V equivalent (confirm)", "note": "Do it", "price": "$25", "links": []}, {"tier": "oe", "name": "Upper and lower timing cover gaskets / RTV (sensor-safe)", "pn": "kit", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "Engine oil and filter", "pn": "—", "note": "Change after; the pan collects plastic", "price": "$60", "links": []}, {"tier": "oe", "name": "DSG-to-engine and propshaft hardware, subframe bolts (torque-to-yield)", "pn": "as found", "note": "Anything TTY you disturb", "price": "varies", "links": []}], "aftermarket": [{"name": "24V VR6 timing tool set (cam locks, crank pin)", "note": "Clone sets are cheap and adequate; the cam lock geometry is the whole point.", "price": "$100–150", "signal": "Required", "links": []}, {"name": "Engine support bar or hoist", "note": "You'll need one or the other.", "price": "$100–300", "signal": "Required", "links": []}], "tools": [{"name": "24V VR6 cam locks and crank locking pin; 27mm socket (upper tensioner bolt) and a long breaker bar"}, {"name": "10, 13, 15, 16, 18mm sockets; 5/6mm hex; triple-squares (DSG and driveline bolts); torque wrenches ¼\" to ½\"; angle gauge"}, {"name": "Engine support bar or hoist; transmission jack; stands; drain pans (oil, coolant, DSG fluid if it comes out)"}, {"name": "RTV, scrapers, magnet, plenty of labelled bags"}], "before": ["Read the Vortex 12V DIY for the chain sequence and photos, then translate to the 24V kit's sheet. Structure is the same; parts and cam locks aren't.", "Decide access before you start: transmission out (DSG + bevel box + propshaft) or engine out. Either is a weekend before you see a chain.", "Order everything TTY you'll disturb. On a 4Motion DSG car that's more than you think."], "steps": [{"n": 1, "title": "Confirm it's the chains", "blocks": [{"t": "text", "b": "Rattle from the rear at idle that follows revs; plastic on the pan magnet; a cam/crank correlation code. If it's a tick from the front instead, look at the tensioner for the accessory belt and the lifters first. This job is too big to do on a guess."}]}, {"n": 2, "title": "Access: transmission out (or engine out)", "caution": true, "blocks": [{"t": "text", "b": "Transmission-out route on a Mk5 R32: battery out; airbox, driver's side engine-bay clutter; exhaust from the downpipe back; propshaft from the bevel box (mark it); front axles from the transmission; subframe lowered or out; DSG unplugged and drained, cooler lines off; engine on a support bar; DSG mount off; bell-housing bolts; DSG and bevel box out as a unit onto a transmission jack. Then the flywheel/driveplate. Now you can see the timing covers."}, {"t": "text", "b": "Engine-out route: many R32 owners judge this easier on a 4Motion car and do the chains, rear main, coolant pipe and mounts on a stand."}, {"t": "warn", "b": "This is where the days go and where things get broken. Bag and label every bolt by location. Propshaft and bevel-box bolts are torque-to-yield and get replaced."}]}, {"n": 3, "title": "Set TDC and lock the cams", "caution": true, "blocks": [{"t": "text", "b": "Turn the engine to cylinder 1 TDC on the marks (crank and cam). Upper timing cover off. The 24V cam lock tool goes into the slots on the cam ends; if it doesn't drop in, you're not at TDC, or you're 360° out. Check the intermediate shaft mark too."}, {"t": "ill", "id": "vr6-chain-hero", "cap": "Upper chain: cams to intermediate shaft. Lower chain: intermediate shaft to crank. Each has a fixed guide rail and a tensioner rail."}, {"t": "warn", "b": "Locks in before anything else comes off, and the crank doesn't move until they're out again. A VR6 that jumps time bends valves."}]}, {"n": 4, "title": "Upper chain, guides and tensioner", "blocks": [{"t": "text", "b": "Upper tensioner bolt out (27mm, with its crush washer). Upper guide rail and tensioner rail off (hex bolts; note which is the curved fixed rail). Upper chain off the cam sprockets and the intermediate sprocket. Inspect the rails: worn or missing plastic is the noise you heard."}, {"t": "torque", "label": "Upper tensioner bolt (27mm) — 12V value", "nm": 100, "c": {"level": "varies", "n": 1, "note": "The 12V DIY's figure; the 24V kit sheet governs. Flagged as unconfirmed for this engine."}}]}, {"n": 5, "title": "Lower chain, guides and tensioner", "blocks": [{"t": "text", "b": "Lower cover off (RTV-sealed; scrape it). Lower tensioner rail (spring type) and guide rail off, lower chain off the intermediate and crank sprockets. Rear main seal is exposed here: pry the old one out, drive the new one in square with a block of wood."}]}, {"n": 6, "title": "New chains on the marks", "caution": true, "blocks": [{"t": "text", "b": "Lower chain onto the crank and intermediate sprockets with both marks aligned per the kit sheet, new guide rail and tensioner rail. Upper chain onto the intermediate and both cam sprockets with the cams still locked, new rails, new upper tensioner bolt with its washer. Only now pull the cam locks. Rotate two full turns by hand and confirm the locks drop back in at TDC."}, {"t": "warn", "b": "If the locks don't drop back in after two turns, take the upper chain off and start again. Do not start the engine."}]}, {"n": 7, "title": "Covers, seal, and everything back", "blocks": [{"t": "text", "b": "RTV the lower cover and fit it; upper cover with its gasket. Flywheel/driveplate with new bolts to the kit's torque. DSG and bevel box back on the jack, bell-housing bolts, mounts, propshaft (new TTY bolts, marks aligned), axles, subframe (TTY, to spec with angle), exhaust, cooler lines, harness, airbox, battery. Fresh oil and filter."}]}, {"n": 8, "title": "First start", "blocks": [{"t": "text", "b": "Crank with coils unplugged for a few seconds to prime, then start. It should be quiet immediately and stay quiet at every idle after. DSG: check fluid level per its guide if any came out. Drive gently, re-check for leaks at both covers and the rear main."}]}], "alsoReplace": [{"name": "Rear main seal", "why": "Exposed with the lower chain off; leaks on high-mileage VR6s."}, {"name": "Engine and transmission mounts", "why": "Everything's out; collapsed mounts are common on R32s."}, {"name": "Coolant pipe, thermostat housing, PCV", "why": "If the engine is out, the top of it is trivial. See their guides."}, {"name": "DSG service and Haldex", "why": "DSG is drained anyway; the Haldex is ten minutes while you're under there."}, {"name": "Bevel box and rear diff oil", "why": "Propshaft's out; plugs are right there."}], "check": {"tab": "Is it the chains?", "title": "Is that noise the chains?", "illId": "vr6-chain-hero", "illCap": "Rear of the engine at idle is the tell.", "rows": [{"see": "Rattle from the transmission side at idle, follows revs", "means": "Guides/tensioner.", "do": "This job. Soon."}, {"see": "Tick from the front, worse cold, fades warm", "means": "Lifters or the accessory tensioner.", "do": "Not the chains; check those first."}, {"see": "Plastic flakes on the pan magnet", "means": "A guide is breaking up.", "do": "Stop driving it hard; this job."}, {"see": "P0016 / P0341 and rough running", "means": "Chain has moved.", "do": "Tow it. Don't start it again."}], "c": {"level": "high", "n": 3, "note": "VR6 forum consensus."}}, "aftercare": ["Oil and filter at 500 miles to clear debris.", "Listen at every cold start for a month."], "disagreements": [{"topic": "Transmission out or engine out?", "pos": "Both camps on R32 forums.", "call": "On a 4Motion DSG car, engine out is often the easier of two hard roads. Pick based on your hoist."}, {"topic": "Home job?", "pos": "'2–8 hours' (12V DIY, chain work only) vs a full weekend-plus (R32 owners, total).", "call": "5 out of 5. Doable with time, tools and a second person; most owners pay for the access at least."}, {"topic": "Chains too, or just guides?", "pos": "Chains rarely wear; guides do.", "call": "Kit. You're not coming back."}], "sources": ["VWVortex 'DIY – Replacing timing chains, tensioners and guides on a 12v VR6' / GruvenParts mirror (structure, technique, tools)", "R32 forum threads on Mk5 chain noise, access and engine-out vs transmission-out", "24V VR6 timing kit listings (INA, Febi) and tool-set listings", "VWVortex 'Common MKV R32 Issues Report'"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'timing-chain-r32';
update tasks set live = true, title = 'Crankcase breather / PCV & valve cover gasket (VR6)', time_label = '5–6 hr', difficulty = 3 where id = 'pcv-r32';
update guides set content = $j${"id": "pcv-r32", "title": "Crankcase breather / PCV & valve cover gasket (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "vr6-top-hero", "alsoFits": "24V VR6: Mk4 R32, Mk4 GTI/Jetta VR6 (24V), Audi A3/TT 3.2, Eos 3.2 — same valve cover and separator", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "5–6 hr (a full afternoon)", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$105 separator · $115 gasket kit", "risk": "Six open intake ports · lots of small fasteners · nose in service position", "why": "On the VR6 the crankcase ventilation isn't a bolt-on valve: the oil separator is built into the front of the valve cover, under the intake manifold. When its diaphragm sticks the engine either pulls a vacuum leak (lean misfire, whistle) or can't vent (pressure pushes oil past the cover gasket and seals). Getting to it is the valve-cover-gasket job, so you do both, and FCP filmed exactly that on a Mk5 R32.", "note": "FCP's step-by-step is the reference and was shot on this car. Owners confirm the afternoon."}, "heroCap": "Under the intake manifold: the valve cover, with the oil separator (the PCV) set into its front on five screws, and the breather hose off the top. The coolant pipe runs alongside.", "lifespan": {"title": "When to expect it", "headline": ["Separator and gasket typically by 100,000 miles; sooner if the car sat"], "earliest": "Whistle or oil at the manifold at 60k", "detail": "Symptoms are either side of the same coin. Stuck open: vacuum leak, lean codes, rough idle, a whistle. Stuck closed: crankcase pressure, oil weeping at the valve cover and around the manifold, sludge and a milky film on the oil from moisture it can't clear. A leaking cover gasket on a VR6 is a reason to suspect the separator, not just the gasket.", "factors": ["Age of the diaphragm", "Short trips (moisture)", "Extended oil changes"], "inspect": ["Oil around the intake manifold base; a whistle at idle; milkiness under the oil cap"], "confidence": {"level": "high", "n": 3, "note": "FCP symptoms list; owner threads agree."}}, "should": {"yesIf": ["Oil build-up around the intake manifold or valve cover", "Whistling with the engine running", "Misfire at idle with lean codes", "Milky film on the oil or sludge under the cap"], "codes": ["P0171", "P0300", "P0507"], "notes": ["Buy both: the oil separator (022 103 515 B) and the valve cover gasket kit (022 103 483 E, with the six plug-tube seals and new bolts). The access is identical, and a new gasket with an old separator leaks again.", "This is the same access as the coolant 'crack pipe' job. If your cooling system is original, do the pipe and thermostat housing in the same session; the manifold is off either way.", "Aftermarket 'catch can' kits for the R32 exist but are rare; the VR6 is port-injected, so the carbon argument doesn't apply. Fix the separator instead."], "confidence": {"level": "high", "n": 3, "note": "FCP procedure on a Mk5 R32; part numbers from FCP and ECS listings."}}, "parts": [{"tier": "oe", "name": "Oil separator (PCV housing)", "pn": "022 103 515 B", "note": "Genuine VW; sits in the valve cover", "price": "$100–120", "links": []}, {"tier": "oem", "name": "Valve cover gasket kit (Elring)", "pn": "022 103 483 E kit", "note": "Gasket, 6 plug-tube seals, bolts", "price": "$100–120", "links": []}, {"tier": "oe", "name": "Intake manifold gasket", "pn": "022 129 717 (confirm by VIN)", "note": "Replace; it's off", "price": "$25", "links": []}, {"tier": "oe", "name": "Oil-resistant RTV (Ultra Black), blue threadlocker", "pn": "—", "note": "Timing-cover joints and the front studs", "price": "$15", "links": []}], "aftermarket": [{"name": "Genuine separator only", "note": "There's no meaningful aftermarket here; the diaphragm has to seal against the cover. Buy VW.", "price": "$100–120", "signal": "OE only", "links": []}], "tools": [{"name": "10mm, 16mm sockets; 5mm and 6mm hex (long ball-end 6mm for the manifold); 10mm triple-square; T20, T25, T30"}, {"name": "Picks, flat screwdrivers, razor blade, extensions; torque wrench 10–13 Nm; jack and stands (bumper bottom screws)"}, {"name": "Drain pan for washer fluid; degreaser; rags for the intake ports"}], "before": ["Engine cold. Battery negative off (you'll be unplugging the coil harness).", "Photograph every connector and vacuum line at the back of the manifold before touching it. There are four lines and a bracket you'll only see by feel.", "Lay a clean sheet out for the manifold, coils and the eleven cover bolts."], "steps": [{"n": 1, "title": "Nose to service position", "blocks": [{"t": "text", "b": "Bumper cover off: eight T25s along the bottom edge, three T25s in each wheel well, both lower grilles (T20), unplug the side markers through the grille openings, disconnect the washer-bottle suction hose (have a pan), four T25s under the lower grilles and two T20s in the main grille opening, two T25s at the top corners by the headlights, then the two T25s to the bumper beam. Pull each corner forward and set the cover somewhere safe."}, {"t": "text", "b": "Behind each headlight, remove the two rear-most T30s. Unclip the hood cable behind the driver's headlight. Remove the top four 16mm bumper-beam bolts and loosen the bottom four almost all the way. Pull the top of the radiator support forward: the nose tilts and the engine opens up."}, {"t": "note", "b": "Twenty minutes that turns a knuckle-buster into a job you can see. Every R32 engine-top write-up does it."}]}, {"n": 2, "title": "Why the nose comes forward", "blocks": [{"t": "text", "b": "The VR6 fills the bay. With the radiator support tilted you can reach the manifold bolts, the brackets behind the manifold and the coils without working blind. FCP: 'achievable in a driveway with hand tools' once you've done this."}]}, {"n": 3, "title": "Intake manifold off", "blocks": [{"t": "text", "b": "Airbox out (clips and tabs; lift). Harness bracket on the driver's side of the head: 10mm nut and stud at the back, T30 at the front; unplug the three throttle-body-side connectors and lay the harness aside. Coil connectors off (lift the tabs with a pick), harness cover off. Walk the main PCV breather hose off the top of the valve cover with a flat screwdriver. Behind the manifold: four vacuum lines by hand and the bracket (10mm triple-square). Throttle body: four 5mm hex. Fuel-line bracket (10mm) on the passenger side. One 10mm triple-square bolt each side of the manifold. Two T30 brackets at the front (dipstick tube, sensors). Vacuum line off the variable-intake solenoid."}, {"t": "text", "b": "Nine manifold bolts, all at the front, long ball-end 6mm hex. Pry the six coils out of the head with a flat screwdriver. Rock the manifold forward to break the gasket's seal and lift it away."}, {"t": "ill", "id": "vr6-top-hero", "cap": "What's under the manifold: valve cover with the oil separator at its front, and the coolant pipe running along the head to the thermostat housing."}, {"t": "warn", "b": "Six open intake ports. Rag them immediately. A dropped bolt into a VR6 port is a head-off job."}]}, {"n": 4, "title": "Valve cover off", "blocks": [{"t": "text", "b": "Eleven 10mm bolts, outer ones first, then the inner. Lift the cover; set it on the bench. Peel off the old gasket and the six plug-tube seals."}]}, {"n": 5, "title": "Swap the oil separator", "caution": true, "blocks": [{"t": "text", "b": "At the front of the cover: five T20 screws hold the separator housing. Remove them, break the housing's seal gently with a flat screwdriver and pop it out. Oil the new housing's gasket, press it in firmly and evenly, five screws snug."}, {"t": "ill", "id": "vr6-top-hero", "cap": "Separator in the front of the cover. It only seats one way; if it's proud on one side, it isn't in."}, {"t": "warn", "b": "Don't lever on the new housing to seat it. Its gasket is the seal that makes the whole job work."}]}, {"n": 6, "title": "New gaskets, cover on", "blocks": [{"t": "text", "b": "New cover gasket into the cover's groove, then the six plug-tube seals. Head face: degreaser on a rag, wiping away from the openings. Razor off the old silicone where the front timing cover meets the head. Dab of oil-resistant RTV in those two spots and at the front corners around the two studs. New bolts in the cover, cover onto the head, tighten in a criss-cross from the middle out."}, {"t": "torque", "label": "Valve cover bolts (10mm ×11)", "nm": 10, "c": {"level": "high", "n": 1, "note": "10 Nm (FCP Euro procedure on a Mk5 R32)."}}]}, {"n": 7, "title": "Manifold on, engine dressed, nose back", "blocks": [{"t": "text", "b": "New manifold gasket pressed into the manifold (pick the old one out; wipe the head face). Manifold on with nothing trapped; all nine bolts started by hand, then tightened middle-out."}, {"t": "torque", "label": "Intake manifold bolts (6mm hex ×9)", "nm": 13, "c": {"level": "high", "n": 1, "note": "13 Nm (FCP Euro procedure on a Mk5 R32)."}}, {"t": "text", "b": "Brackets (T30), variable-intake vacuum line, coils in (tab side per the connectors), harness and cover, manifold side bolts (10mm TS), driver's-side harness bracket (ground stud at the rear hole), PCV breather hose onto the cover, fuel-line bracket, four vacuum lines and their bracket, throttle body (5mm hex, hand-start), airbox and MAF."}, {"t": "text", "b": "Nose: lift it back, four T30s behind the headlights, top beam bolts by hand then all eight to torque (16mm), then the cover in reverse: two beam T25s, side markers, washer hose, grilles, corner screws, bottom edge, wheel wells."}]}, {"n": 8, "title": "Start and check", "blocks": [{"t": "text", "b": "Battery on. Start it: whistle gone, idle steady. Drive, then look at the cover seam and the manifold base for oil after a few heat cycles. Pull the oil cap: gentle suction, not a howl."}]}], "alsoReplace": [{"name": "Coolant pipe and thermostat housing", "why": "Same access; both are age-failed plastic. See its guide and do them in this session."}, {"name": "Spark plugs and coils", "why": "Coils are in your hand and the plugs are exposed."}, {"name": "Intake manifold gasket", "why": "Always, when the manifold is off."}, {"name": "Fuel injector o-rings", "why": "If the fuel rail comes off for room, new o-rings."}], "check": {"tab": "Open or closed?", "title": "Which way did it fail?", "illId": "vr6-top-hero", "illCap": "Two failure modes, one part.", "rows": [{"see": "Whistle, lean codes, rough idle", "means": "Separator stuck open: vacuum leak.", "do": "Separator + gasket."}, {"see": "Oil at the cover seam and manifold base, milky oil cap", "means": "Stuck closed: crankcase pressure.", "do": "Separator + gasket; check the rear main seal for weep too."}, {"see": "Gasket leak, separator fine when tested", "means": "Just an old gasket.", "do": "Replace the separator anyway; the access is the whole cost."}], "c": {"level": "high", "n": 2, "note": "FCP symptom list; owner reports."}}, "aftercare": ["Re-check the cover seam after a week.", "If you skipped the crack pipe, put it on the list."], "disagreements": [{"topic": "Service position or not?", "pos": "Some owners work with the nose in place.", "call": "Tilt it. The manifold bolts alone justify it."}, {"topic": "Separator only or with the gasket?", "pos": "The separator can be changed with the cover on the bench either way.", "call": "Both, always. Same access."}], "sources": ["FCP Euro 'How To Replace A Volkswagen VR6 Valve Cover Gasket & PCV' (Mk5 R32)", "ECS / FCP part listings (022 103 515 B, gasket kit)", "R32 owner threads on PCV symptoms"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'pcv-r32';
update tasks set live = true, title = 'Aftermarket intake (R32)', time_label = '1 hr', difficulty = 2 where id = 'intake-r32';
update guides set content = $j${"id": "intake-r32", "title": "Aftermarket intake (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "airbox-tsi", "alsoFits": "Mk5 R32 only (Mk4 R32 and A3/TT 3.2 kits differ)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake?", "hint": "All the R32 kits replace the airbox with a filter on a pipe to the throttle body and move the factory MAF into the new pipe.", "options": [{"id": "neuspeed", "label": "Neuspeed P-Flo", "when": "Filter on a short pipe; heat shield; the most common."}, {"id": "carbonio", "label": "APR Carbonio", "when": "Carbon pipe; premium; same layout."}, {"id": "other", "label": "VF / BSH / Evolution / other", "when": "Same shape; follow the kit sheet."}]}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$300–600", "risk": "MAF handling · clamps under tension", "why": "On a naturally aspirated VR6 an intake is mostly about the noise, and the noise is the reason people buy an R32. Power gains are a handful of horsepower up top; the induction howl is immediate. The factory airbox lifts out on clips, so this is one of the easier jobs on the car.", "note": "FCP's R32 valve-cover write-up confirms the airbox is clips and tabs; kit sheets from Neuspeed and APR cover the rest."}, "heroCap": "Factory airbox at the front-left of the bay on clips, a duct to the throttle body with the MAF in it. Kits replace the box and duct with a filter and a pipe; the MAF moves over.", "lifespan": {"title": "When owners do this", "headline": ["Early. It's the R32 mod."], "earliest": null, "detail": "Nothing wears out; owners do it for sound. Some go back to stock for heat-soak reasons in summer; a kit with a real heat shield helps.", "factors": ["Want the noise", "Heat soak in traffic (pick a shielded kit)"], "inspect": ["Filter every oil change"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus."}}, "should": {"yesIf": ["You want the VR6 to sound like a VR6", "Replacing a tired factory airbox anyway"], "codes": [], "notes": ["The MAF is a slot sensor in a housing; the kit's pipe must match its bore or the car runs lean and throws codes. Real kits are designed for it.", "Oiled cotton filters: oil lightly or the MAF fouls. Dry filters avoid the question.", "Heat: the VR6 bay is hot. Kits with a proper shield around the filter (Neuspeed, Carbonio) keep intake temps sane in traffic."], "confidence": {"level": "medium", "n": 3, "note": "Kit documentation and owner threads."}}, "parts": [{"tier": "aftermarket", "name": "R32 intake kit", "pn": "see options below", "note": "Pipe, filter, shield, clamps, MAF adapter", "price": "$300–600", "links": []}], "aftermarket": [{"name": "Neuspeed P-Flo (Mk5 R32)", "note": "Short pipe, dry filter, heat shield on the factory airbox mounts. The forum default; good sheet.", "price": "$300–350", "signal": "Forum favorite", "links": []}, {"name": "APR Carbonio", "note": "Carbon-fibre pipe and box, premium finish, retains a shielded enclosure.", "price": "$500–600", "signal": "Premium", "links": []}, {"name": "VF Engineering / BSH / Evolution Motorsports", "note": "Same layout, different hardware. VF's is well regarded on the 3.2 TT.", "price": "$350–500", "signal": "Alternatives", "links": []}], "tools": [{"name": "Flat screwdriver for the clamps; T25; pliers for the breather hose"}, {"name": "Phillips for the MAF screws (handle the sensor by its housing)"}], "before": ["Engine cold.", "Lay the kit out against its list.", "Note where the breather hose from the valve cover joins the factory duct; the kit has a port for it."], "steps": [{"n": 1, "title": "Factory box out", "blocks": [{"t": "text", "b": "Unplug the MAF. Loosen the clamp at the throttle body and pull the duct off. Disconnect the breather hose from the duct. The airbox sits in the chassis on clips and tabs: release the clips and lift the whole box and duct out as one piece."}, {"t": "ill", "id": "airbox-tsi", "cap": "Same corner of the bay as the drawing; the R32 box lifts out on clips rather than screws."}]}, {"n": 2, "title": "MAF across", "blocks": [{"t": "text", "b": "Two screws hold the MAF into the factory duct. Slide it out and into the kit's pipe with the kit's screws, arrow toward the throttle body. Housing only; don't touch the element."}]}, {"n": 3, "title": "Kit in", "blocks": [{"t": "text", "b": "Heat shield onto the factory airbox mounts (Neuspeed, Carbonio) or the kit's bracket. Coupler onto the throttle body, clamp loose. Pipe into the coupler, filter onto the pipe, clamp loose. Breather hose to the kit's port.", "only": ["neuspeed", "carbonio", "other"]}]}, {"n": 4, "title": "Relax, then tighten", "caution": true, "blocks": [{"t": "text", "b": "Everything sitting with no twist, filter clear of the fender liner and the coolant reservoir? Now tighten every clamp. MAF plugged in. Start it; a stumble for a minute is the ECU adapting."}, {"t": "warn", "b": "A coupler tightened under tension pops off the throttle body on the first hard pull. Relaxed first, tight second."}]}], "alsoReplace": [{"name": "Spark plugs and coils", "why": "The engine cover's off and you've heard the induction noise; a misfire will ruin it. If they're due, now."}], "check": {"tab": "Which kit?", "title": "Which kit?", "illId": "airbox-tsi", "illCap": "Sound first; shielding second.", "rows": [{"see": "Want the sound, daily driver", "means": "A shielded kit.", "do": "Neuspeed P-Flo."}, {"see": "Want it to look the part under the hood", "means": "Carbon.", "do": "APR Carbonio."}, {"see": "Budget", "means": "Any real kit beats an eBay pipe: the MAF bore matters.", "do": "VF or BSH used."}], "c": {"level": "community", "n": 3, "note": "Owner threads."}}, "aftercare": ["Check clamps after a week.", "Filter cleaning per the maker."], "disagreements": [{"topic": "Power?", "pos": "Vendors claim 5–10 hp.", "call": "A few, at the top. Buy it for the noise."}], "sources": ["FCP Euro Mk5 R32 write-up (airbox removal)", "Neuspeed and APR R32 intake sheets and listings", "VWVortex R32 intake threads"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'intake-r32';
update tasks set live = true, title = 'Exhaust: cat-back, downpipes & headers (R32)', time_label = '3–4 hr+', difficulty = 2.5 where id = 'exhaust-r32';
update guides set content = $j${"id": "exhaust-r32", "title": "Exhaust: cat-back, downpipes & headers (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-exhaust-hero", "alsoFits": "Mk5 R32 only; Mk4 R32 and Golf R systems differ", "category": "Engine", "kind": "upgrade", "variants": {"question": "How far are you going?", "hint": "The stock system has a vacuum-operated valve in the muffler (the 'flapper') that opens with revs. Cat-backs keep or replace it; downpipes and headers are a bigger job with emissions implications.", "options": [{"id": "catback", "label": "Cat-back", "when": "Sound and a lighter rear; keeps the cats. A single day."}, {"id": "downpipes", "label": "Downpipes / test pipes", "when": "Removes the cats; off-road only in most places. More sound, some power on a tuned car."}, {"id": "headers", "label": "Headers (manifolds)", "when": "The real power step on an NA VR6 and the biggest job; usually with cams and a tune."}]}, "glance": {"timeFirst": "3–4 hr (cat-back) · a day+ (downpipes/headers)", "timeRepeat": "2 hr", "difficulty": 2.5, "cost": "$700–1,800 cat-back · $500–1,200 downpipes · $1,500+ headers", "risk": "Hot parts · seized flange nuts · the propshaft runs right there", "why": "The R32's exhaust is its own system: twin manifolds into a single 60mm downpipe with two cats, a mid-pipe past the propshaft to a centre-exit muffler with a vacuum flapper. A cat-back swaps the mid-pipe and muffler and is where the VR6 sound lives. Downpipes and headers are for owners chasing power on top of cams and a tune.", "note": "ECS's R32 cat-back PDF is the reference for the stock system; the exhaust megathread covers what owners run and why."}, "heroCap": "Underneath: downpipe with the cats ahead of the cross brace, a single 60mm joint into the cat-back, mid-pipe running beside the propshaft, muffler with the vacuum flapper and centre-exit tips.", "lifespan": {"title": "When owners do this", "headline": ["Cat-back: the classic first R32 mod. Pipes ahead of the cats rot by 150k on salt-belt cars."], "earliest": null, "detail": "Nothing forces the cat-back; it's sound. High-mileage cars do rust through the downpipe section ahead of the cats, so an exhaust job sometimes starts as a repair.", "factors": ["Want the noise", "Rust belt", "Cams and a tune (headers)"], "inspect": ["Look at the pipes ahead of the cats when the car's up for anything else"], "confidence": {"level": "community", "n": 3, "note": "Owner threads."}}, "should": {"yesIf": ["Want the VR6 to be heard", "Rusted mid-pipe or muffler", "Building an NA VR6 with cams (headers)"], "codes": [], "notes": ["The flapper: the stock muffler valve is vacuum-actuated and normally closed, opening with revs for volume. Some cat-backs keep a valve (ECS's is remote-controlled), most delete it. If you keep the factory muffler and want it open all the time, unplugging and capping the vacuum line leaves it closed, not open; owners wire a switch instead.", {"text": "Sleeve clamp joint: the cat-back meets the stock downpipe at a single 60mm sleeve clamp ahead of the cross brace. Every cat-back uses that joint; no cutting.", "only": ["catback"]}, {"text": "Removing the cats removes the emissions equipment. Not street-legal in most of the US, and the ECU will throw P0420/P0430 without a tune or spacers. Know what you're buying.", "only": ["downpipes"]}, {"text": "Headers on a VR6 are a manifold-off job at the back of the engine against the firewall, with the downpipe and often the transmission-side heat shields in the way. Pair with cams and a tune or don't bother; the gain on a stock engine is small.", "only": ["headers"]}], "confidence": {"level": "medium", "n": 3, "note": "ECS PDF for the stock system; owner megathread for options and results."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back system", "pn": "see options below", "note": "Mid-pipe, muffler, tips, clamp; hangers transfer from stock", "price": "$700–1,800", "links": [], "only": ["catback"]}, {"tier": "aftermarket", "name": "Downpipes / test pipes (with or without high-flow cats)", "pn": "USP, Scorpion, Milltek", "note": "Off-road use", "price": "$500–1,200", "links": [], "only": ["downpipes"]}, {"tier": "aftermarket", "name": "Headers + downpipes", "pn": "Milltek manifolds, others", "note": "With cams and a tune", "price": "$1,500+", "links": [], "only": ["headers"]}, {"tier": "oe", "name": "Exhaust hangers (×4), flange gaskets, clamp", "pn": "—", "note": "Hangers tear; replace", "price": "$40", "links": []}], "aftermarket": [{"name": "Milltek cat-back (resonated / non-resonated)", "note": "The reference R32 system. Resonated is civil; non-res is loud.", "price": "$1,200–1,800", "signal": "Forum favorite", "links": []}, {"name": "Borla cat-back", "note": "Deep and quiet cruising, loud on throttle; owners praise the tone.", "price": "$900–1,200", "signal": "Best daily tone", "links": []}, {"name": "Magnaflow cat-back", "note": "Value; non-resonated attracts attention, per owners.", "price": "$700–900", "signal": "Value", "links": []}, {"name": "ECS valved cat-back", "note": "Keeps a muffler valve with a remote. The PDF this guide follows.", "price": "$1,000–1,300", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_14107_VW_MK5_R32_Exhaust_System_Installation_r1.pdf"}]}, {"name": "USP downpipes / race pipe", "note": "The downpipe of choice on the megathread; catted and catless versions.", "price": "$600–1,000", "signal": "Downpipe pick", "links": [], "only": ["downpipes", "headers"]}, {"name": "'Tampa mod' resonator delete", "note": "Budget: cut the resonator, weld in a straight pipe or a bigger resonator. Owners love the sound per dollar.", "price": "$100–200 at a shop", "signal": "Budget", "links": [], "only": ["catback"]}], "tools": [{"name": "13mm and 15mm sockets, ratchet, breaker bar; exhaust hanger pliers"}, {"name": "Jack, four stands; penetrating oil; ball-pein hammer for slip joints"}, {"name": "Downpipes/headers: 16mm and triple-square for flange hardware, heat, patience", "only": ["downpipes", "headers"]}], "before": ["Exhaust cold.", "Soak the sleeve clamp and any flange nuts the night before.", "Lay the new system out and test-fit every slip joint on the floor (ECS: tap them round with a hammer if they don't slide)."], "steps": [{"n": 1, "title": "Raise the car, support the exhaust", "blocks": [{"t": "text", "b": "Four stands. Support the system from below (a jack with a board). Remove the four 13mm nuts holding the chassis cross brace and set the brace aside."}]}, {"n": 2, "title": "Stock cat-back off", "only": ["catback", "downpipes", "headers"], "blocks": [{"t": "text", "b": "Loosen the sleeve clamp between the downpipe and the cat-back and slide it forward onto the downpipe. Disconnect the vacuum line from the muffler valve. Pop the two front hangers with the pliers. Unbolt the muffler hangers from the body. Lower the whole system and slide it out."}, {"t": "ill", "id": "r32-exhaust-hero", "cap": "One sleeve joint ahead of the brace, two front hangers, bolted muffler hangers, and the flapper's vacuum line."}]}, {"n": 3, "title": "Downpipes off", "only": ["downpipes", "headers"], "caution": true, "blocks": [{"t": "text", "b": "With the cat-back out: unplug the O2 sensors (note which is which), remove the flange nuts at both manifolds (soak, heat if needed), any bracket to the transmission, and work the downpipe assembly out past the subframe. Transfer the O2 sensors to the new pipes."}, {"t": "warn", "b": "Manifold studs snap. Heat, oil, patience, and a stud kit on the shelf before you start."}]}, {"n": 4, "title": "Headers", "only": ["headers"], "caution": true, "blocks": [{"t": "text", "b": "With the downpipes off: heat shields, manifold nuts (from below and behind; the rear bank is against the firewall), old manifolds out. New gaskets, headers in with new nuts in a criss-cross, then the downpipes to the headers. This is the step owners describe as a day by itself."}, {"t": "warn", "b": "The rear manifold nuts are reached blind. Label the tools that fit before you're under there."}]}, {"n": 5, "title": "New system in, loose", "blocks": [{"t": "text", "b": "Transfer the stock hangers to the new mid-pipe and muffler in the same orientation. Extension/mid-pipe into the downpipe with the sleeve clamp, then the muffler, then the tips: all snug, nothing torqued, no impact gun."}]}, {"n": 6, "title": "Clearance, hangers, tips", "caution": true, "blocks": [{"t": "text", "b": "Walk the system: clearance to the propshaft, the subframe and the trunk floor at the mid-pipe; to the heat shields and the cross brace at the front. Hangers level side to side and pitched so the lower hole sits 10–15 mm forward of the upper (they swing back as it heats). Centre the tips in the valance cut-outs and set their depth."}, {"t": "warn", "b": "The propshaft is what a GTI doesn't have. A mid-pipe that kisses it shows up as a vibration at speed and a polished line on the pipe. Check it with the car on the ground too."}]}, {"n": 7, "title": "Tighten front to back", "blocks": [{"t": "text", "b": "Push each joint upward as you tighten its clamp, front to back. Let it settle; re-walk the clearances. Vacuum line to the muffler valve if the new system has one. Cross brace back on (13mm), belly pans."}]}, {"n": 8, "title": "Start, drive, re-check", "blocks": [{"t": "text", "b": "Start it and listen for leaks at the joints. Drive; a new rattle over bumps is a hanger or a heat shield. Re-check every clamp at 500 miles (ECS)."}]}], "alsoReplace": [{"name": "Exhaust hangers", "why": "Rubber, twenty years old, and you have pliers in your hand."}, {"name": "Cross-brace nuts", "why": "Rusty; new ones now."}, {"name": "O2 sensors", "why": "If they're original and the downpipes are off, new ones save a second flange fight.", "only": ["downpipes", "headers"]}], "check": {"tab": "How loud?", "title": "How much exhaust do you want?", "illId": "r32-exhaust-hero", "illCap": "Sound and legality run in opposite directions.", "rows": [{"see": "Daily driver, want the VR6 note", "means": "Resonated cat-back.", "do": "Milltek resonated or Borla."}, {"see": "Weekend car, want to be heard", "means": "Non-resonated.", "do": "Milltek non-res or Magnaflow non-res."}, {"see": "Budget", "means": "Resonator delete.", "do": "Tampa mod at a muffler shop."}, {"see": "Cams, tune, track", "means": "Headers and downpipes.", "do": "Headers + USP pipes, and accept the emissions reality."}], "c": {"level": "community", "n": 3, "note": "Exhaust megathread."}}, "aftercare": ["Clamps at 500 miles.", "Look at the mid-pipe's propshaft clearance after the first hot drive."], "disagreements": [{"topic": "Power from a cat-back?", "pos": "Vendors imply gains.", "call": "None worth measuring on an NA VR6. It's sound and weight."}, {"topic": "Flapper", "pos": "Delete it, keep it, switch it.", "call": "Most cat-backs delete it. If you keep the stock muffler, wire a switch; capping the vacuum leaves it closed."}, {"topic": "Downpipes on a street car", "pos": "Popular on the megathread.", "call": "Not legal in most places. Say so, and decide."}], "sources": ["ECS Tuning 'MK5 R32 Valved Exhaust System Installation' PDF (stock system removal, clearances, hangers)", "VWVortex 'Official MkV R32 Exhaust Thread' and 'exhaust system for mk5 r32'", "Milltek, Borla, Magnaflow, USP listings"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'exhaust-r32';
